 short=base+[operate('lesson-intake','deliver'),dict(action='WAIT_FOR_IDS',ids=['cue-ready'],until=119),dict(action='SET',target='public-project',fields={'excerpt':excerpt,'seconds':28,'track':'music','picture':'hands','credit':'Rue'}),operate('public-render','render'),operate('public-render','publish'),operate('lobby-intake','accept'),operate('lobby-intake','load'),operate('subscriber-service','activate',account='subscriber-D18',invoice='L18',edition='full-lesson'),write('main','Tonight’s closing tune is up—28 seconds here and on the foyer screen. Subscribers, your full lesson is ready too.|今晚结尾那段放啦，公开和大厅屏幕是28秒版，订阅的完整课也好了。'),write('old-answer','They are different editions: subscribers keep the full lesson; the public excerpt is short.|是不同版本，订阅者保留完整课，公开仅短片。'),reply('lesson-q','Yes. Your full lesson is retained; only the public and foyer editions use the short closing excerpt.|能拿，完整课保留，只有公开和大厅版用短结尾。'),reply('subscriber-dm','The producer has accepted the full lesson. Your page is sandbox://batch017/t1-03/lesson.|制作人已收到整节课。你可以在这里观看：sandbox://batch017/t1-03/lesson。'),reply('venue-dm','The accepted P1 excerpt is now loaded in the foyer player, with music and hands-only footage.|P1已接收片段现装入大厅播放器，仅音乐和手部画面。'),finish('All three standing editions delivered with separate scopes; optional teaser omitted.|三份既有版本按各范围交付，额外预告未做。')]
 near=swap(short,'public-project',dict(action='SET',target='public-project',fields={'excerpt':'latest','seconds':seconds,'track':'music','picture':'hands','credit':'Rue'}),'SET') if branch=='B' else omit(short,lambda a:a.get('choice')=='load')
 wrong=swap(short,'public-project',dict(action='SET',target='public-project',fields={'excerpt':excerpt,'seconds':28,'track':'teaching','picture':'full','credit':'Rue'}),'SET')
 x.c['changed_fact']=T('Only the latest closing excerpt duration in the actual cue sheet changes:28 seconds in A,34 in B.|仅实际曲目单中最新结尾时长改变：A28秒，B34秒。')
 return install_plans(x,short,near,g1 if branch=='B' else g2,wrong,g1)


