 result['plans']['image_only']=dict(actions=omit(short,lambda a:a.get('target')=='tutorial-alt' and a.get('action')=='WRITE'),notes=T('All pixels and delivered files are corrected, but the independent public alt description still identifies the same withdrawn plate.|像素及已交文件全修，但独立公开alt描述仍识别同一撤回车牌。'),failed_goals={g1:T('The current optional alt still contains the identifiable plate.|当前可选alt仍含可识别车牌。')})
