def hotel(branch='A'):
 x=start('t1-04','The invitation after the hotel actually accepts the room|酒店实际接房后的邀请','Please lock one room for our creator meetup by16:30 and keep the accepted arrival services working. Guests arrive at17:00 and leave20:00. The eligible vote favours A only if everyone has a step-free round trip. We already owe a station shuttle, a concierge key handover and a level-entry transfer for Ren. Publish the invitation from the actual confirmed room and tell guests where they will really be met. Stay until the17:00 arrival handover is recorded.|请16:30前锁一间创作者聚会房，保留已接来程服务。17:00来、20:00走，登记票优先A但须全员来回无台阶。车站接驳、礼宾交钥匙和Ren平入口接应都已约。按实际确认房发邀请，告诉客人真实接应点，留守到17:00到场交接有记录。','Hotel reception desk15:00. One unit per minute, deadline t180=18:00. Holds expire t90. A destination request, accepted shuttle job, actual arrival and key handover are separate states.|酒店接待台15:00，一单位一分钟，t180为18:00截止，预留t90失效。目的地请求、接驳受理、真实到场、交钥匙分别记录。',style='precise',deadline=180)
 x.source('vote','Eligible room rule and tally|有效选房规则与票',txt('vote','Registered A11/B7. Both900,20 seats. Choose A if a step-free street-room-street route covers16:50–20:00, otherwise B.|登记A11/B7，两处900、20座。A街面到房间再出在16:50–20:00全程无台阶才选A，否则B。'))
 end='20:30' if branch=='A' else '18:00'
 x.source('routes','Dated complete routes|当日完整路线',txt('routes','Sunday A side ramp16:30–'+end+', connects street/lift/room. A main door has six steps, no other level exit after side closure. B street ramp16:30–20:30 reaches room directly.|周日A侧坡16:30–'+end+'，通街面电梯房间；正门六阶，侧门关后无平出口。B街坡16:30–20:30直达房间。'))
 x.source('holds','Current room holds and assigned-bay rule|当前预留与卸客位规则',field('room-state','Actual room transaction|实际房间交易',{'selected':None,'A_hold':True,'B_hold':True,'paid':0}),txt('holds','Confirming one room by16:30 costs900. The accepted room assigns a private guest drop-off bay. Shuttle and accessible-transfer jobs must use that actual bay, not a guessed front door.|16:30前确认一间900，实际接房后分配客人卸客位。接驳及平入口服务须用实际分配位，不可猜正门。'))
 x.source('shuttle-contract','Accepted station shuttle|已接车站接驳',dm('shuttle-dm','I’m booked for Pat and Jo at the station. Send the accepted hotel bay through dispatch. I arrive at the hotel at17:00; a route edit in the invitation won’t update my job.|我已接车站Pat和Jo。实际酒店卸客位走派车台，17:00到酒店，改邀请不会改我的任务。','Shuttle'),field('shuttle-job','Actual accepted shuttle destination|实际接驳去向',{}),field('arrival','Actual hotel arrival manifest|实际酒店到场清单',{}),field('arrival-state','Actual arrival state|实际到场状态',{'arrived':False,'Pat_verified':False}),txt('pat-claim','Pat’s room-key booking claim is P17. Similar display-name booking P71 belongs to another party; a shuttle guest list alone is not a key ownership claim.|Pat房钥匙报名凭证P17，同名P71是另一组，接驳名单不等于钥匙权利凭证。'))
 x.source('concierge-contract','Existing concierge key-custody promise|已有礼宾钥匙保管承诺',dm('concierge-dm','I hold the meetup key. Room acceptance identifies its actual key number; dispatch’s accepted drop-off bay tells me where I can hand it to Pat. I cannot mark the key delivered until Pat actually arrives.|聚会钥匙我保管。房间确认才确定实际钥匙号，派车受理卸客位决定我在哪交Pat。Pat真到后才记交付。','Concierge'),field('key-state','Actual room-key custody|实际房门钥匙保管',{'number':None,'owner':'concierge','handover':False}))
 x.source('access-contract','Ren’s existing level-entry transfer|Ren已有平入口接应',dm('ren-dm','Please keep the level-entry transfer. No front steps, and no need to say why in the group.|请保留平入口接应，不走正门台阶，群里不用解释原因。','Ren'),field('access-job','Actual accepted Ren transfer job|实际已接Ren接应任务',{}),field('access-state','Ren actual transfer state|Ren实际接应状态',{'dispatched':False,'completed':False}),field('access-completed','Actual completed transfer route|实际完成接应路线',{}))
 x.source('guest','Guest’s existing arrival thread|客人现来程会话',dm('pat-dm','We’re on the station shuttle. Should I get the room key at the old front desk?|我们坐车站接驳，还是旧前台拿房钥匙？','Pat'))
 x.source('history','Our existing invitation and stale key reply|我方邀请与旧钥匙回复',post('main','Meetup17:00–20:00, A front steps. Pick up the room key at the old front desk.|聚会17:00–20:00，A正门台阶，旧前台取钥匙。'),thread('key-q','Where will the key be if we come together?|一起到的话，钥匙在哪？','Jo'),old('old-key','The concierge will leave it at the front steps before anyone arrives.|还没到也会先放正门台阶。','key-q'))
