 sch={'venue':['A','B'],'bay':['A-side','B-ramp']}
 desk(x,'shuttle-dispatch','Shuttle actual dispatch|接驳实际派车','shuttle-dispatch','The accepted card becomes the actual driver instruction. An arrival record at17:00 follows that accepted destination.|受理卡会成为实际司机指令，17:00到场记录按该去向。',{'update':option('Update accepted station shuttle destination|更新已接车站接驳去向',schema=sch,parameter_record={'resource':'shuttle-job','field':'instruction'},requires={'revealed':['room-receipt']})})
 x.c['events'].append(dict(id='shuttle-arrival',at=120,when={'attributes':{'shuttle-job':{'fields':{'instruction':{'venue':'A' if branch=='A' else 'B','bay':'A-side' if branch=='A' else 'B-ramp'}}}}},copy=[{'from':'shuttle-job','to':'arrival','attributes':['fields']}],set={'arrival-state':{'arrived':True}},add=[txt('arrival-receipt','Pat and Jo actually arrived on the accepted shuttle at its recorded bay.|Pat和Jo实际随已接接驳到记录卸客位。','receipt')]))
 desk(x,'concierge','Concierge actual handover|礼宾实际交接','concierge','Accept a concrete key handover point after the hotel and shuttle terms exist; hand over the actual room key only when the named guest arrives.|酒店及接驳条款成立后接具体交钥匙点，具名客人到场后才交实际房钥匙。',{'verify':option('Match actually arrived Pat to booking claim|核实际到场Pat与报名凭证',schema={'claim':['P17','P71']},parameter_record={'resource':'arrival-state','field':'Pat_claim'},requires={'fields':{'arrival-state':{'arrived':True}}},set={'arrival-state':{'Pat_verified':True}}),'book':option('Accept actual Pat key-handover job|接Pat实际交钥匙任务',schema={'guest':['Pat'],'venue':['A','B'],'bay':['A-side','B-ramp'],'key':['KA','KB']},parameter_record={'resource':'key-state','field':'job','field_map':{'key':'number'}},requires={'revealed':['room-receipt']}),'handover':option('Hand room key to arrived Pat|向已到Pat交房钥匙',requires={'fields':{'arrival-state':{'arrived':True,'Pat_verified':True}}},set={'key-state':{'owner':'Pat','handover':True}})})
 desk(x,'access','Actual level-entry transfer desk|实际平入口接应台','access','Keep Ren’s accepted service, using the actual selected room’s level bay. This does not reveal the private reason.|保留Ren已接服务，用实际选房平卸客位，不公开私人原因。',{'update':option('Update accepted Ren transfer instruction|更新已接Ren接应指令',schema=sch,parameter_record={'resource':'access-job','field':'instruction'},requires={'revealed':['room-receipt']}),'dispatch':option('Dispatch Ren’s booked level-entry transfer at actual arrival|实际来时派出Ren已订平入口接应',requires={'fields':{'arrival-state':{'arrived':True}}},set={'access-state':{'dispatched':True}})})
 x.c['action_events'].append(dict(id='ren-transfer-complete',trigger={'action':'OPERATE','target':'access','choice':'dispatch'},delay=2,copy=[{'from':'access-job','to':'access-completed','attributes':['fields']}],set={'access-state':{'completed':True}},add=[txt('ren-transfer-complete','The booked assistant met Ren at the accepted level bay and completed the transfer to the recorded destination.|已订助手在受理平卸客位接到Ren，实际送到记录目的地。','receipt')]))
 door=desk(x,'door-pass','Hotel party gate-pass service|酒店同行人员门禁凭证','door-pass','A room key does not open the privately managed level entrance. After the room is actually accepted, issue its dated party M7 gate pass. Keep the code in private arrival services; do not print it in the public invitation.|房钥匙打不开另管的平路入口。房间实际确认后签当日同行M7门禁码，仅给私人来程服务，不印公开邀请。',{'issue':option('Issue actual dated level-entry party pass|签实际当日平路同行门禁码',schema={'venue':['A','B']},param_variants=[dict(param_values={'venue':'A'},requires={'fields':{'room-state':{'selected':'A'}}},set={'door-state':{'issued':True,'venue':'A','pass':'PASS-A-SUN','party':'M7'}},add=[txt('door-receipt','M7 Sunday A-side gate pass issued: PASS-A-SUN. Valid for this party’s accepted room and level gate only.|M7周日A侧门码PASS-A-SUN已签，仅本同行已确认房及平门禁可用。','receipt')]),dict(param_values={'venue':'B'},requires={'fields':{'room-state':{'selected':'B'}}},set={'door-state':{'issued':True,'venue':'B','pass':'PASS-B-SUN','party':'M7'}},add=[txt('door-receipt','M7 Sunday B-ramp gate pass issued: PASS-B-SUN. Valid for this party’s accepted room and level gate only.|M7周日B坡门码PASS-B-SUN已签，仅本同行已确认房及平门禁可用。','receipt')])],inspect=['door-state'])})
 x.c['resources'][0]['entries']=[e for e in x.c['resources'][0]['entries'] if e['key']!='door-pass'];x.c['lookups'].pop('card/door-pass')
 x.c['lookups']['card/access-contract'].extend([door,field('door-state','Actual private dated party gate credential|实际私人当日同行门禁凭证',{'issued':False})])
 for target in ['shuttle-dispatch','access']:
  svc=x.find(target);opt=next(o for o in svc['options'] if o['key']=='update');opt['param_schema']['entry_pass']={'type':'string'}
  x.c['operations'][target+'/update']['param_schema']['entry_pass']={'type':'string'}
