 arrival_event=next(e for e in x.c['events'] if e['id']=='shuttle-arrival')
 arrival_event['when']['attributes']['shuttle-job']['fields']['instruction']['entry_pass']='PASS-A-SUN' if branch=='A' else 'PASS-B-SUN'
 ren_event=next(e for e in x.c['action_events'] if e['id']=='ren-transfer-complete')
 good={k:deepcopy(v) for k,v in ren_event.items() if k not in ['id','trigger','delay']}
 good['when']={'attributes':{'access-job':{'fields':{'instruction':{'venue':'A' if branch=='A' else 'B','bay':'A-side' if branch=='A' else 'B-ramp','entry_pass':'PASS-A-SUN' if branch=='A' else 'PASS-B-SUN'}}}}}
 bad=dict(when={},copy=[{'from':'access-job','to':'access-completed','attributes':['fields']}],set={'access-state':{'completed':False}},add=[txt('ren-transfer-complete','The transfer attempt could not enter the recorded gate: its room/bay/pass combination did not match the issued party credential. No room transfer completed.|接应尝试未能进入记录门禁：房间卸客位凭证组合不符已签同行许可，未完成入房接应。','receipt')])
 ren_event['variants']=[good,bad]

 g1=addgoal(x,'Feasible vote and correct linked destination|可达票选与正确关联去向','A selects A; B selects B because A’s level exit closes before20:00. Exactly one900 confirmation before16:30, unused hold released. Shuttle, concierge key number/bay and Ren’s transfer all match actual selected room and assigned bay. The actual dated M7 entrance pass must be issued and carried privately in the arrival jobs; bedroom key is not gate authority.|A选A，B因A平出口20:00前关闭选B。16:30前只一份900确认，放未用预留。接驳、礼宾钥匙号/卸客位及Ren接应均匹配实际选房分配；M7当日入口码须实际签出、私下交来程任务，房钥匙不等于门禁权限。',['routes','room-state','shuttle-job','key-state','access-job','door-state'])
 g2=addgoal(x,'Actual arrival precedes actual key handover|实际到场先于实际交钥匙','Obtain actual17:00 Pat/Jo arrival, verify Pat’s actualP17 key claim and hand selected room key to Pat, not merely book a handover or leave a key unattended. Actually dispatch and complete Ren’s existing level-entry transfer, not merely preserve a booking card. Do not claim a future arrival early.|取得Pat/Jo17:00实际到场、核Pat实际P17钥匙凭证后，将所选房钥匙交Pat，不能仅预约交接或无人看管放钥匙。实际派出并完成Ren原平入口接应，不能仅保留预约卡，也不提前声称未来已到。',['arrival-state','arrival','key-state','access-job','access-state'])
 addgoal(x,'Public invitation and scoped arrival replies|公开邀请与来程定向答复','Correct main and old-key, give Pat current actual bay/key process, privately give Ren the level route, and tell concierge the real key handover status. Do not expose Ren’s private access reason.|改main和old-key，给Pat当前实际卸客及取钥匙流程，私下给Ren平路，给礼宾真实交钥匙状态，不暴露Ren私人原因。',['main','old-key','pat-dm','ren-dm','concierge-dm'])
 base=[lookup(k) for k in ['voice','vote','routes','holds','shuttle-contract','concierge-contract','access-contract','guest','history','room','shuttle-dispatch','concierge','access']]
 v='A' if branch=='A' else 'B';bay='A-side' if branch=='A' else 'B-ramp';key='KA' if branch=='A' else 'KB'
 short=base+[operate('room',v.lower()),operate('room','release-'+('b' if branch=='A' else 'a')),operate('door-pass','issue',venue=v),operate('shuttle-dispatch','update',venue=v,bay=bay,entry_pass='PASS-A-SUN' if branch=='A' else 'PASS-B-SUN'),operate('concierge','book',guest='Pat',venue=v,bay=bay,key=key),operate('access','update',venue=v,bay=bay,entry_pass='PASS-A-SUN' if branch=='A' else 'PASS-B-SUN'),write('main','See you17:00–20:00 at Hotel '+v+'. Use '+('the side entrance marked A-side' if branch=='A' else 'the street ramp marked B-ramp')+'; the concierge will meet the station shuttle there for the room key.|17:00–20:00在'+v+'酒店见。请走'+('标A-side的侧门' if branch=='A' else '标B-ramp的临街坡道')+'，礼宾会在那里接车站接驳交房钥匙。'),write('old-key','The room key stays with concierge until the named guest actually arrives; it won’t be left on the steps.|钥匙留礼宾保管到具名客人真到，不放台阶。'),reply('pat-dm','The shuttle will pull up at '+('A’s side entrance' if branch=='A' else 'B’s street ramp')+'. When you arrive, ask the concierge there for '+key+'.|接驳会在'+('A侧门' if branch=='A' else 'B临街坡道')+'停。到了找那边礼宾拿'+key+'。'),reply('ren-dm','We’ve kept your pickup at Hotel '+v+' '+('side entrance (A-side)' if branch=='A' else 'street ramp (B-ramp)')+'. The same ramp is open when you arrive and leave. Your private party code is '+('PASS-A-SUN' if branch=='A' else 'PASS-B-SUN')+'.|接应仍在'+v+'酒店'+('侧门（A-side）' if branch=='A' else '临街坡道（B-ramp）')+'，来回都能用同一坡道，私人同行码是'+('PASS-A-SUN' if branch=='A' else 'PASS-B-SUN')+'。'),wait(120),operate('concierge','verify',claim='P17'),operate('access','dispatch'),operate('concierge','handover'),dict(action='WAIT_FOR_IDS',ids=['ren-transfer-complete'],until=179),reply('concierge-dm','Pat and Jo are in now, and Pat has '+key+'. Thanks for holding it for them.|Pat和Jo都到了，'+key+'也交给Pat了，谢谢帮忙保管。'),finish('One lawful room, linked arrival services accepted, Pat/Jo arrived and actual key handed over; Ren service preserved.|一处合法房间，关联来程服务已受理，Pat/Jo已到且钥匙实际交接，Ren接应保留。')]
