 x.c['lookups']['card/property'].append(field('part-return','Actual removable-part return custody|实际可拆部件归还保管',{}))
 x.source('scope','Current recipient-specific choice|当前接收人范围选择',txt('scope-note','Nia’s existing seat permission does not include Ora. A generic yes to “tell them” is insufficient for a seat transfer. Kai can instead meet at the public help point without their seat being relayed.|原座位许可给Nia，不包括Ora，泛泛“告诉他们吧”不够转座位。也可Kai到公开求助点会合，不用转座位。'))
 x.source('meeting','Standing lawful area-meeting option|既有合法区域会合方案',dm('meeting','If I don’t want a seat visit from the new lead, I can meet at the blue help point. Please keep the camera sealed until I show claim C18.|如果不想新负责人到座位，我可到蓝色求助点。出示C18领物凭证前相机封袋。','Kai'),txt('claim','Claim C18 belongs to Kai/K18. Claim C81 is the other recorder’s owner. Public aliases are not ownership proof.|C18为Kai/K18领物凭证，C81为另一录音机主人，公开昵称不证明所有权。'))
 x.source('handover-state','Actual distinct case ownership|实际独立事件负责人',field('case-state','Actual handover and interventions|实际交班与干预',{'kai_owner':'Nia','lee_owner':'Nia','lee_patrol':'pending','meeting':None,'claim_verified':False}))
 x.source('history','Old public help status|旧公开求助状态',post('main','Any volunteer with a matching name can take over our private help cases.|任何同名志愿者都能接私人求助。'),old('old-case','A handover message means the camera has already been returned.|交班消息发出就等于相机归还。'))
 x.source('ora','Incoming lead’s verified conversation|核验接班负责人会话',dm('ora-dm','I can accept the two cases after14:30. For the camera I need the sealed item, its ownership token and the allowed meeting point; not the private screenshot.|14:30后可接两案。相机要封袋物品、所有权凭证和获准会合点，不要私人截图。','Ora'))
 x.answer('kai-dm','incoming',('Yes, you may give C3-08 in text to Ora for the camera return; still no screenshot.|可以把C3-08文字给Ora送相机，仍不要截图。' if branch=='A' else 'No seat to Ora, please. I’ll use the blue help point and show C18.|别给Ora座位，我到蓝色求助点出示C18。'),delay=1,details={'recipient':'Ora','information':'seat-text','purpose':'camera-return'},fields={'seat_allowed':branch=='A'},rid='kai-scope')
 desk(x,'charging','Actual charging-cabinet release|实际充电柜取物','charging','Release actual item to Nia using a concrete cabinet token. Incorrect existing tokens return the other physical device, not an ownership approval.|用具体柜票把实际物品交Nia，已有错误柜票会交另一实物，不代表所有权正确。',{'take':option('Take a camera/recorder against a token|凭柜票取相机或录音机',schema={'token':['T18','T81'],'slot':['P4','P5']},param_variants=[dict(param_values={'token':'T18','slot':'P4'},set={'item':{'id':'K18','owner':'Kai','holder':'Nia','sealed':False,'sd_card':'SD-ORG-7','sd_owner':'fair-library','battery':'B18','battery_owner':'Kai'}}),dict(param_values={'token':'T81','slot':'P5'},set={'item':{'id':'R81','owner':'Other','holder':'Nia','sealed':False,'sd_card':'SD-OTHER','sd_owner':'Other','battery':'B81','battery_owner':'Other'}})]),'return-part':option('Return one actual removable part to registered library custodian Mae|将一件实际可拆部件归还登记图书馆保管员Mae',schema={'component':['sd-card','battery']},param_variants=[dict(param_values={'component':'sd-card'},requires={'fields':{'item':{'holder':'Nia'}},'not':{'fields':{'item':{'sd_card':None}}}},copy=[{'from':'item','to':'part-return','attributes':['fields']}],post_set={'item':{'sd_card':None,'sd_owner':None},'part-return':{'returned_component':'sd-card','custodian':'Mae','received':True}}),dict(param_values={'component':'battery'},requires={'fields':{'item':{'holder':'Nia'}},'not':{'fields':{'item':{'battery':None}}}},copy=[{'from':'item','to':'part-return','attributes':['fields']}],post_set={'item':{'battery':None,'battery_owner':None},'part-return':{'returned_component':'battery','custodian':'Mae','received':True}})],inspect=['part-return','item']),'seal':option('Seal the actually collected item for handover|封袋实际取出物品备交班',requires={'fields':{'item':{'holder':'Nia'}}},set={'item':{'sealed':True}})})
 desk(x,'handover','Actual case and item handover|实际事件及物品交接','handover','After14:30 accept each case independently; craft-aisle case C2 carries only its area, not the reporter name. Transfer moves the physical sealed item into Ora’s custody; a local note does not.|14:30后逐案接管，手作过道事件C2只带区域、不带求助者姓名；转交会把封袋实物交Ora，本地记一笔不算。',{'kai':option('Ora accepts Kai case|Ora接Kai事件',requires={'time':{'minimum':30}},set={'case-state':{'kai_owner':'Ora'}}),'lee':option('Ora accepts anonymous craft-aisle case C2|Ora接匿名手作过道事件C2',requires={'time':{'minimum':30}},set={'case-state':{'lee_owner':'Ora'}}),'item':option('Transfer sealed actual device to Ora|封袋实际设备交Ora',requires={'fields':{'item':{'sealed':True,'holder':'Nia'},'case-state':{'kai_owner':'Ora'}}},set={'item':{'holder':'Ora'}})})
 desk(x,'floor','Actual area intervention and item meeting|实际区域干预与领物会合','floor','Area patrol needs no reporter identity. Set a concrete allowed meeting, verify the owner’s actual claim and then hand over the actual held item.|区域巡查不需举报人身份。设具体获准会合点，核本人实际领物凭证，再交实际保管物品。',{'patrol':option('Complete craft-aisle rule check|完成手作过道规则检查',requires={'fields':{'case-state':{'lee_owner':'Ora'}}},set={'case-state':{'lee_patrol':'completed'}}),'meeting':option('Arrange actual item-return meeting|安排实际物品归还会合',schema={'place':['C3-08','blue-help-point']},parameter_record={'resource':'case-state','field':'meeting'},requires={'fields':{'case-state':{'kai_owner':'Ora'}}}),'claim':option('Verify physical claimant’s presented claim|核实实物领取者出示凭证',schema={'claim':['C18','C81']},parameter_record={'resource':'case-state','field':'claim'},set={'case-state':{'claim_verified':True}}),'return':option('Hand actual held device to verified claimant|将实际保管设备交已核领取者',requires={'fields':{'case-state':{'claim_verified':True},'item':{'holder':'Ora'}}},set={'item':{'holder':'claimant','returned':True}})})
 g1=addgoal(x,'Recipient-specific privacy and correct device identity|接收人隐私范围与正确设备','Nia’s seat permission does not cover Ora. If asking, A permits only seat text to Ora, B uses blue-help-point and never relays seat. A may also use the standing lawful blue-help-point. Lee remains area-only. Return camera K18 from T18/P4 to actual claim C18, never the similarly named other recorder. The institution SD-ORG-7 must be actually returned to its registered library custodian, not handed with Kai’s camera; retain Kai’s own body and B18 battery. Equivalent actual authorised component return is valid.|Nia座位许可不覆盖Ora。若问，A仅给Ora座位文字，B用蓝求助点不转座位；A也可用既有蓝求助点。Lee仅区域。须T18/P4取K18交实际C18凭证者，不能误交同名另一录音机；机构SD-ORG-7须实际退登记图书馆保管员，不能夹给Kai，保留Kai机身及B18电池；等价真实获准部件归还有效。',['kai-scope','meeting','claim','item','camera-order','part-return'])
 g2=addgoal(x,'Actual case and item custody before closure|结案前实际事件与实物交接','Collect K18, seal and physically transfer it after Ora actually accepts Kai case; independently accept and complete Lee area patrol. Actual claim verification and device handover close Kai. Generic handover acknowledgment cannot stand in for physical device return or patrol completion.|取K18、封袋，Ora实际接Kai事件后实物转交；Lee事件独立接管并完成区域巡查。核实际领物凭证和实物交付后才结Kai，笼统交班消息不等于相机归还或巡场完成。',['item','case-state'])
 addgoal(x,'Scoped messages and history maintenance|范围消息与历史维护','Correct main and old-case, privately tell Kai actual return and Lee actual area result, and give Ora only ownership token/device and allowed meeting information. No screenshot, Lee identity or private reason goes to public volunteers.|改main和old-case，私下给Kai实际归还、Lee实际区域结果，给Ora仅所有权票设备及获准会合信息；不给公开志愿者截图、Lee身份或私人原因。',['main','old-case','kai-dm','lee-dm','ora-dm'])
