 result['plans']['wrong_part']=dict(actions=[dict(a,params={'component':'battery'}) if a.get('choice')=='return-part' else deepcopy(a) for a in short],notes=T('The institution card is confused with Kai’s own battery: the battery is surrendered while the loaned card stays in the returned body.|把机构卡和Kai自有电池混淆：退了电池，借卡反而随机身还给Kai。'),failed_goals={g1:T('Actual component ownership and return are wrong.|实际部件物权及归还错误。')})
